'use strict';
// The same SLOTS entries drive the category strip, worn indicators and ordering.
const HAIR_CATEGORIES=[['front','前'],['back','后'],['single','单品']];
let hairPositionKey="";
let mobileView='full',lastContext='',paletteIndex=-1,tailorItem=null,tailorPanel='',featureHandled=false;
state.hairMode=state.hairMode==='single'?'single':'multiple';
const baseMobileRender=render,baseClothingSlots=clothingSlots;
const slotRows=()=>SLOTS.filter(([slot])=>catalog.some(i=>i.slot===slot));
const wornIn=slot=>Object.entries(state.equipped).filter(([key,id])=>key===slot||key.startsWith(slot+':'));
clothingSlots=function(){const defaults=baseClothingSlots();return [...new Set([...(state.layerOrder||[]).filter(s=>defaults.includes(s)),...defaults])];};
mobileClothingOrder=function(){let box=$('#clothing-order');if(!box){box=document.createElement('div');box.id='clothing-order';box.className='wear-status';document.querySelector('.stage').after(box);}box.innerHTML=slotRows().map(([slot,label])=>`<div class="wear-slot"><button data-undress="${slot}" aria-label="${label}：${wornIn(slot).length?'已穿，点击脱下':'未穿'}" aria-pressed="${!!wornIn(slot).length}">${label}</button><span><button data-layer="${slot}" data-step="1" aria-label="${label}向上叠放">↑</button><button data-layer="${slot}" data-step="-1" aria-label="${label}向下叠放">↓</button></span></div>`).join('');box.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.undress){for(const [key]of wornIn(b.dataset.undress))delete state.equipped[key];}if(b.dataset.layer){const rows=clothingSlots(),from=rows.indexOf(b.dataset.layer),to=Math.max(0,Math.min(rows.length-1,from+Number(b.dataset.step)));[rows[from],rows[to]]=[rows[to],rows[from]];state.layerOrder=rows;state.clothingOrder=rows.indexOf('top')>rows.indexOf('bottom')?'top':'bottom';}persist();render();};};
function preferredRegion(){return tab==='hair'||tab==='face'?'face':tab==='looks'?'full':tab==='tailor'?(item(tailorItem)?.slot||category):category==='jewelry'?'face':'full';}
function focusRegion(region,force=false){const context=tab+':'+(tab==='clothes'?category:region);if(force||context!==lastContext){mobileView=region;lastContext=context;}const stage=$('.stage'),settings={full:[1,0],face:[3.2,12],top:[2.4,-28],bottom:[1.8,-65],dress:[1.2,-12],coat:[1.5,-15],shoes:[3,-235],socks:[2.5,-180],bra:[2.2,-30],briefs:[2.4,-80],bag:[1.6,-30],jewelry:[3.2,12]};const [scale,shift]=settings[mobileView]||settings.top;if(!window.MobileEditUI?.ownsCamera()){stage.style.setProperty('--figure-zoom',scale);stage.style.setProperty('--figure-shift',shift+'%');}let control=$('#view-controls');if(!control){control=document.createElement('div');control.id='view-controls';stage.append(control);control.onclick=e=>{const b=e.target.closest('[data-view-mode]');if(b){mobileView=b.dataset.viewMode==='full'?'full':preferredRegion();focusRegion(preferredRegion());}};}control.innerHTML=`<button data-view-mode="detail" aria-pressed="${mobileView!=='full'}">${tab==='hair'||tab==='face'||preferredRegion()==='face'?'脸部':'细节'}</button><button data-view-mode="full" aria-pressed="${mobileView==='full'}">全身</button>`;}
function mobileHairColorControls(hair){const p=HairDye.palette(hair.color,hair.tones),hex=v=>'#'+v.map(c=>Math.round(c).toString(16).padStart(2,'0')).join('');return '<div class="hair-control-row hair-color-row"><span class="hair-row-title">COLOR</span><div class="hair-custom-colors">'+[['','自定义',hair.color],['shadow','阴影',hex(p.shadow)],['highlight','高光',hex(p.highlight)]].map(([key,label,value])=>'<label title="'+label+'"><input type="color" '+(key?'data-hair-tone="'+key+'"':'')+' aria-label="'+label+'" value="'+value+'"><span>'+label+'</span></label>').join('')+'</div><div class="mobile-swatches" aria-label="预设发色">'+hair.palette.map(([color,name,scheme],index)=>'<button data-palette="'+index+'" class="'+(index===hair.schemeIndex?'selected':'')+'" style="--swatch:'+color+'" aria-label="'+esc(name)+'">'+(scheme?.kind==='highlight'?'<span class="hair-highlight-mark" aria-hidden="true">≋</span>':'')+'</button>').join('')+'</div><input type="hidden" id="palette-hex" value="'+hair.color+'"><input type="hidden" id="palette-name" value="'+esc(hair.palette[paletteIndex]?.[1]||'')+'"></div>';}
function mobileHairPlacementControls(hair){
 const rows=HairStudio.consumer.categoryCatalog(hairSide).filter(i=>hair[i.side].includes(i.id)).map(i=>({...i,category:hairSide}));
 if(!rows.some(i=>i.side+':'+i.id===hairPositionKey))hairPositionKey=rows[0]?rows[0].side+':'+rows[0].id:'';
 const row=rows.find(i=>i.side+':'+i.id===hairPositionKey),front=hairSide==='front',piece=hairSide==='single',selected=front?[...rows].sort((a,b)=>hair[a.side].indexOf(a.id)-hair[b.side].indexOf(b.id)):[],idx=selected.findIndex(i=>i===row),layer=row?hair.placement?.[hairPositionKey]||'behind':'behind';
 const options=rows.length?rows.map(i=>'<option value="'+i.side+':'+i.id+'" '+(hairPositionKey===i.side+':'+i.id?'selected':'')+'>'+esc(i.name)+'</option>').join(''):'<option>'+ (piece?'未选择单品':'未选择头发')+'</option>';
 const actions=front?'<button data-hair-order="back" '+(state.hairMode!=='multiple'||selected.length<2||idx===0?'disabled':'')+'>后一层</button><button data-hair-order="front" '+(state.hairMode!=='multiple'||selected.length<2||idx===selected.length-1?'disabled':'')+'>前一层</button>':(piece?[['behind','身体后'],['front','身体前']]:[['behind','发梢后'],['front','发梢前']]).map(([value,label])=>'<button data-player-hair-layer="'+value+'" data-origin="'+(row?.side||'back')+'" data-piece="'+(row?.id||'')+'" aria-pressed="'+(!!row&&layer===value)+'" '+(!row?'disabled':'')+'>'+label+'</button>').join('');
 return '<div class="hair-control-row hair-position-row"><span class="hair-row-title">位置</span><select data-hair-position aria-label="调整哪片头发" '+(!rows.length?'disabled':'')+'>'+options+'</select><div class="hair-position-actions">'+actions+'</div></div>';
}
function renderHair(){const hair=HairStudio.consumer.get();$('#categories').innerHTML=HAIR_CATEGORIES.map(([id,name])=>`<button data-side="${id}" class="${hairSide===id?'active':''}">${name}</button>`).join('');$('#hair-colors').innerHTML='<div class="hair-control-row hair-mode-row"><div class="hair-mode-slider" data-mode="'+state.hairMode+'" role="group" aria-label="发型选择模式"><i aria-hidden="true"></i><button data-no-i18n data-hair-mode="single" aria-pressed="'+(state.hairMode==='single')+'">SINGLE</button><button data-no-i18n data-hair-mode="multiple" aria-pressed="'+(state.hairMode==='multiple')+'">MULTIPLE</button></div><button data-hair-auto-tones title="恢复自动阴影与高光">自动色调</button><button data-hair-remove-all>全部取下</button></div>'+mobileHairColorControls(hair)+mobileHairPlacementControls(hair);$('#items').innerHTML=HairStudio.consumer.categoryCatalog(hairSide).map(i=>`<button class="item ${hair[i.side].includes(i.id)?'selected':''}" data-player-hair="${i.id}" data-origin="${i.side}" aria-label="${esc(i.name)}"><img src="${esc(i.thumbnail)}" alt="" loading="lazy"><span>${esc(i.name)}</span></button>`).join('');}
function selectedInCategory(hair,cat){return HairStudio.consumer.categoryCatalog(cat).filter(i=>(hair[i.side]||[]).includes(i.id));}
function choosePlayerHair(side,id){hairPositionKey=side+':'+id;const hair=HairStudio.consumer.get(),selected=selectedInCategory(hair,hairSide),already=hair[side].includes(id);if(!already&&state.hairMode==='multiple'&&selected.length>=2){toast('每个分类最多选 2 款');return;}if(!already&&state.hairMode==='single')for(const i of selected)hair[i.side]=hair[i.side].filter(v=>v!==i.id);hair[side]=already?hair[side].filter(v=>v!==id):[...hair[side],id];HairStudio.consumer.restore(hair);render();}
function nameHairColor(){let dialog=$('#hair-color-name-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='hair-color-name-dialog';dialog.className='hair-color-name-dialog';document.body.append(dialog);}dialog.innerHTML='<form><h2>保存发色</h2><label>颜色名字<input name="name" aria-label="颜色名字" required maxlength="24" autofocus></label><div><button type="button" data-cancel>取消</button><button type="submit">保存</button></div></form>';dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.querySelector('form').onsubmit=e=>{e.preventDefault();$('#palette-name').value=dialog.querySelector('input').value.trim();if(!$('#palette-name').value)return;dialog.close();const button=document.createElement('button');button.setAttribute('data-palette-save','');$('#hair-colors').onclick({target:button});};dialog.showModal();}
function storePalette(rows){localStorage.setItem('wardrobe-mobile-palette-v1',JSON.stringify(rows));HairStudio.consumer.setPalette(rows);}
function unlockColor(i){if(!tailorUnlocked()){renderTailorGate();return;}tailorPanel='color';render();}

const originalMobileFigure=figure;figure=function(){const selected=window.MobilePreview?.current()||(tab==='tailor'?MobileTailor.current():null);if(!selected)return originalMobileFigure();const previous=state.equipped;state.equipped={...previous};if(tab==='tailor'){if(['top','dress','bra'].includes(selected.slot))delete state.equipped.coat;if(selected.slot==='bra'){delete state.equipped.top;delete state.equipped.dress;}if(selected.slot==='briefs'){delete state.equipped.bottom;delete state.equipped.dress;}if(selected.slot==='socks')delete state.equipped.shoes;if(selected.slot==='top'&&!state.equipped.bottom){const bottom=item(state.split?.bottom)||catalog.find(i=>i.slot==='bottom'&&PlayerEconomy.owns(i.id));if(bottom)state.equipped.bottom=bottom.id;}}if(selected.slot==='dress'){delete state.equipped.top;delete state.equipped.bottom;}if(['top','bottom'].includes(selected.slot))delete state.equipped.dress;if(selected.slot==='jewelry'){if(!Object.values(state.equipped).includes(selected.id)){const rows=wornIn('jewelry');if(rows.length>=3)delete state.equipped[rows[rows.length-1][0]];state.equipped['jewelry:'+selected.id]=selected.id;}}else{for(const [key]of wornIn(selected.slot))delete state.equipped[key];state.equipped[selected.slot]=selected.id;}try{return originalMobileFigure();}finally{state.equipped=previous;}};
render=function(){if(tab==='tailor'&&!window.WordrobeFeatures?.tailor)tab='clothes';normalizeHairLimit();$('.mobile-app').dataset.tab=tab;MobileTailor.decorate(catalog);baseMobileRender();if(tab==='hair')renderHair();if(tab==='tailor')renderTailor();const tailorFooter=$('#tailor-footer');if(tailorFooter)tailorFooter.hidden=tab!=='tailor'||!tailorUnlocked();focusRegion(preferredRegion());if(!featureHandled){const target=new URLSearchParams(location.search).get('unlock');if(window.WordrobeFeatures?.tailor&&target?.startsWith('recolor:')&&item(target.slice(8))){featureHandled=true;tailorItem=target.slice(8);tab='tailor';category=item(tailorItem).slot;tailorPanel=PlayerEconomy.owns(target)?'color':'';render();if(!PlayerEconomy.owns(target))unlockColor(item(tailorItem));}}};
const oldItemsClick=$('#items').onclick;
$('#items').onclick=e=>{const b=e.target.closest('button');if(b?.dataset.playerHair){choosePlayerHair(b.dataset.origin,b.dataset.playerHair);return;}if(b?.dataset.tailorItem){tailorItem=b.dataset.tailorItem;tailorPanel='';render();return;}if(b?.dataset.tailorSwatch){MobileTailor.setColor(b.dataset.tailorSwatch).then(syncTailorTools).catch(e=>toast(e.message));return;}if(b?.dataset.tailorAction){handleTailor(b);return;}if(b?.dataset.pattern){MobileTailor.pattern(b.dataset.pattern).then(()=>syncTailorTools()).catch(e=>toast(e.message));return;}oldItemsClick(e);};
$('#items').onchange=null;
$('#hair-colors').onchange=e=>{if(e.target.matches('[data-hair-position]')){hairPositionKey=e.target.value;render();}};
$('#hair-colors').oninput=e=>{const input=e.target;if(input.dataset.hairTone){if(/^#[0-9a-f]{6}$/i.test(input.value)){HairStudio.consumer.tones({...HairStudio.consumer.get().tones,[input.dataset.hairTone]:input.value});HairDye.syncControls($('#hair-colors'),HairStudio.consumer.get().color,HairStudio.consumer.get().tones);}return;}if(input.matches('input[type=color]')||input.id==='palette-hex'){const value=input.value;if(/^#[0-9a-f]{6}$/i.test(value)){HairStudio.consumer.color(value);$('#palette-hex').value=value;$('#hair-colors input[type=color]').value=value;HairDye.syncControls($('#hair-colors'),value,HairStudio.consumer.get().tones);window.FigureView?FigureView.paint($('#figure'),figure()):$('#figure').innerHTML=figure();}}};
$('#hair-colors').onclick=e=>{const b=e.target.closest('button');if(!b)return;const hair=HairStudio.consumer.get();if(b.hasAttribute('data-hair-auto-tones')){HairStudio.consumer.tones({});render();return;}if(b.dataset.hairOrder){const [side,id]=hairPositionKey.split(':');HairStudio.consumer.reorder(side,id,b.dataset.hairOrder);render();return;}if(b.dataset.playerHairLayer){HairStudio.consumer.setPlacement(b.dataset.origin,b.dataset.piece,b.dataset.playerHairLayer);render();return;}if(b.dataset.hairToneAuto){delete hair.tones[b.dataset.hairToneAuto];HairStudio.consumer.tones(hair.tones);HairDye.syncControls($('#hair-colors'),hair.color,hair.tones);return;}if(b.hasAttribute('data-hair-remove-all')){HairStudio.consumer.restore({...hair,front:[],back:[]});render();return;}if(b.dataset.hairMode){state.hairMode=b.dataset.hairMode;for(const [cat]of HAIR_CATEGORIES){const selected=selectedInCategory(hair,cat),limit=state.hairMode==='single'?1:2;for(const i of selected.slice(0,-limit))hair[i.side]=hair[i.side].filter(id=>id!==i.id);}HairStudio.consumer.restore(hair);persist();render();return;}if(b.dataset.palette!==undefined){paletteIndex=Number(b.dataset.palette);HairStudio.consumer.selectColorScheme(paletteIndex);render();return;}if(b.hasAttribute('data-palette-new')){paletteIndex=-1;render();return;}if(b.hasAttribute('data-palette-delete')){hair.palette.splice(paletteIndex,1);storePalette(hair.palette);paletteIndex=-1;render();return;}if(b.hasAttribute('data-palette-save')){const name=$('#palette-name').value.trim(),hex=$('#palette-hex').value;if(!name){nameHairColor();return;}if(!/^#[0-9a-f]{6}$/i.test(hex)){toast('填写六位色号');return;}if(paletteIndex<0){hair.palette.push([hex,name]);paletteIndex=hair.palette.length-1;}else hair.palette[paletteIndex]=[hex,name,...(hair.palette[paletteIndex]?.[2]?[hair.palette[paletteIndex][2]]:[])];storePalette(hair.palette);HairStudio.consumer.selectColorScheme(paletteIndex);render();toast('已保存');}};
const tailorTab=document.createElement('button');tailorTab.dataset.tab='tailor';tailorTab.textContent='裁缝铺';if(window.WordrobeFeatures?.tailor)$('.main-tabs').insertBefore(tailorTab,document.querySelector('[data-tab=looks]'));
const tailorText=(zh,en)=>I18n.lang()==='en'?en:zh;
const garmentLabel=i=>i.customName?(I18n.lang()==='en'?i.nameEn:i.name):I18n.t(GarmentNames.clean(i.name));
function tailorIcon(kind){const paths={color:'M12 3 4 13a8 8 0 0 0 16 0Z',print:'M12 3v18M3 12h18M5 5l14 14M5 19 19 5',reset:'M4 10a8 8 0 1 1 1 9M4 4v6h6',save:'M4 3h14l3 3v15H3V3Zm3 0v7h10V3M7 21v-7h10v7'};return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[kind]}" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round"/></svg>`;}
function syncTailorTools(){if(tab!=='tailor')return;const busy=MobileTailor.busy(),dirty=MobileTailor.dirty(),recipe=MobileTailor.recipe();for(const b of document.querySelectorAll('#items [data-tailor-action],#tailor-footer [data-tailor-action]')){b.disabled=busy||((b.dataset.tailorAction==='save'||b.dataset.tailorAction==='reset')&&!dirty)||(b.dataset.tailorAction==='undo'&&!MobileTailor.canUndo())||(['color','print','save','draft'].includes(b.dataset.tailorAction)&&!PlayerEconomy.owns(tailorItem));}for(const b of $('#items').querySelectorAll('[data-tailor-swatch]')){b.disabled=busy||!PlayerEconomy.owns(tailorItem);b.setAttribute('aria-pressed',String(recipe.color?.toLowerCase()===b.dataset.tailorSwatch));}for(const input of document.querySelectorAll('#tailor-options input,#tailor-options [data-pattern]'))input.disabled=busy||!PlayerEconomy.owns(tailorItem);const colorInput=$('#tailor-options input[type=color]');if(colorInput)colorInput.value=MobileTailor.color();for(const b of $('#items').querySelectorAll('[data-pattern]'))b.setAttribute('aria-pressed',String(recipe.pattern?.id===b.dataset.pattern));const layout=$('#tailor-layout');if(layout){layout.hidden=!recipe.pattern;for(const input of layout.querySelectorAll('input'))input.disabled=busy||!PlayerEconomy.owns(tailorItem);}const status=$('#tailor-status');if(status)status.textContent=busy?tailorText('正在保存…','Saving…'):dirty?tailorText('草稿预览 · 保存后才创建新衣服','Draft preview · Save to create a new item'):tailorText('选择改色或印花开始','Choose Recolor or Print to begin');}
window.addEventListener('tailor-draft',syncTailorTools);
function renderTailor(){if(!tailorUnlocked()){renderTailorGate();return;}const available=catalog.filter(i=>!i.testProduct&&(i.capabilities?.recolor||i.capabilities?.print));$('#categories').hidden=false;$('#categories').innerHTML=slotRows().filter(([slot])=>available.some(i=>i.slot===slot)).map(([slot,label])=>`<button data-category="${slot}" class="${category===slot?'active':''}">${label}</button>`).join('');let i=item(tailorItem);if(!i||i.slot!==category||!available.includes(i)){i=available.find(i=>i.slot===category)||available[0];tailorItem=i?.id;tailorPanel='';if(i)category=i.slot;}
if(!i){$('#items').innerHTML='<div class="empty">还没有可改色或印花的衣服</div>';return;}MobileTailor.select(i);window.MobilePreview?.clear();
if(!['color','print'].includes(tailorPanel)||!i.capabilities[tailorPanel==='color'?'recolor':'print'])tailorPanel=i.capabilities.recolor?'color':'print';
const tool=(action,label,en)=>`<button id="tailor-tab-${action}" role="tab" data-tailor-action="${action}" aria-label="${tailorText(label,en)}" aria-selected="${tailorPanel===action}" aria-controls="tailor-tab-panel" tabindex="${tailorPanel===action?0:-1}">${tailorIcon(action)}<span>${tailorText(label,en)}</span></button>`;
$('#items').innerHTML=`<div class="tailor-garments">${available.filter(row=>row.slot===category).map(row=>`<button class="item ${i.id===row.id?'selected':''}" data-tailor-item="${row.id}" aria-pressed="${i.id===row.id}" aria-label="${esc(garmentLabel(row))}" ${row.customName?'data-no-i18n-attrs':''}><img src="${esc(row.thumbnail||row.image)}" alt=""><span data-no-i18n>${esc(garmentLabel(row))}</span><small>${PlayerEconomy.owns(row.id)?'✓':itemPrice(row)+' '+tailorText('积分','Points')}</small></button>`).join('')}</div><div class="tailor-tools"><nav class="tailor-sidebar" role="tablist" aria-label="${tailorText('定制功能','Customization')}" aria-orientation="vertical">${i.capabilities.recolor?tool('color','改色','Recolor'):''}${i.capabilities.print?tool('print','印花','Print'):''}</nav><section id="tailor-tab-panel" role="tabpanel" aria-labelledby="tailor-tab-${tailorPanel}"><strong data-no-i18n>${esc(garmentLabel(i))}</strong>${!PlayerEconomy.owns(i.id)?`<button class="tailor-unlock-item" data-tailor-action="garment">${tailorText('解锁衣服','Unlock Item')} · ${itemPrice(i)}</button>`:''}<p id="tailor-status" role="status"></p><div id="tailor-options"></div></section></div>`;
let footer=$('#tailor-footer');if(!footer){footer=document.createElement('div');footer.id='tailor-footer';document.querySelector('.closet').append(footer);footer.onclick=e=>{const b=e.target.closest('[data-tailor-action]');if(b)handleTailor(b);};}footer.hidden=false;footer.innerHTML=EditUI.toolbar('tailor',MobileTailor.canUndo(),MobileTailor.drafts().length);
$('.tailor-sidebar').onkeydown=e=>{const rows=[...document.querySelectorAll('.tailor-sidebar [role=tab]:not(:disabled)')];let n=rows.indexOf(e.target);if(n<0||!['ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();n=e.key==='Home'?0:e.key==='End'?rows.length-1:(n+(e.key==='ArrowDown'?1:-1)+rows.length)%rows.length;const id=rows[n].id;rows[n].click();document.getElementById(id)?.focus();};
window.FigureView?FigureView.paint($('#figure'),figure()):$('#figure').innerHTML=figure();const host=$('#tailor-options'),recipe=MobileTailor.recipe(),layout=recipe.layout||{x:.5,y:.3,scale:.55};
if(tailorPanel==='color')host.innerHTML=`<div class="tailor-presets" aria-label="${tailorText('预设色','Preset Colors')}">${[['#f2e8d8','象牙白','Ivory'],['#d6c3a3','燕麦','Oat'],['#c98f94','烟粉','Dusty Rose'],['#792e43','酒红','Burgundy'],['#82917c','鼠尾草绿','Sage'],['#809db0','雾蓝','Mist Blue'],['#35465d','海军蓝','Navy'],['#33302e','墨黑','Ink']].map(([hex,zh,en])=>`<button data-tailor-swatch="${hex}" style="--swatch:${hex}" aria-label="${tailorText(zh,en)}" aria-pressed="${MobileTailor.color()===hex}"><i aria-hidden="true"></i><span>${tailorText(zh,en)}</span></button>`).join('')}</div><label class="tailor-color"><span>衣服颜色</span><input type="color" aria-label="衣服颜色" value="${MobileTailor.color()}"></label>`;
if(tailorPanel==='print'){host.innerHTML='<input class="tailor-search" type="search" aria-label="搜索印花" placeholder="搜索印花"><div id="tailor-pattern-list"></div>'+`<div id="tailor-layout" ${recipe.pattern?'':'hidden'}>${[['scale','印花大小',.15,1],['x','水平位置',.1,.9],['y','垂直位置',0,.85]].map(([key,label,min,max])=>`<label><span>${label}</span><input data-layout="${key}" type="range" aria-label="${label}" min="${min}" max="${max}" step=".01" value="${layout[key]}"></label>`).join('')}</div>`;MobileTailor.showPatterns($('#tailor-pattern-list')).then(syncTailorTools).catch(e=>{const list=$('#tailor-pattern-list');if(list){list.innerHTML=`<button data-tailor-action="retry">${tailorText('印花加载失败，点击重试','Prints failed to load. Retry')}</button>`;}toast(e.message);});}
host.oninput=e=>{if(e.target.type==='search'){const q=e.target.value.toLowerCase();host.querySelectorAll('[data-pattern]').forEach(b=>b.hidden=!b.getAttribute('aria-label').toLowerCase().includes(q));}if(e.target.type==='color')MobileTailor.setColor(e.target.value).catch(e=>toast(e.message));if(e.target.dataset.layout){const values=Object.fromEntries([...host.querySelectorAll('[data-layout]')].map(n=>[n.dataset.layout,Number(n.value)]));MobileTailor.layout(values).catch(e=>toast(e.message));}};syncTailorTools();}
function openTailorNames(){let dialog=$('#tailor-name-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='tailor-name-dialog';document.body.append(dialog);}const names=MobileTailor.names();dialog.innerHTML=`<form><h2>给新衣服起名</h2><p>保存后会作为独立衣服加入衣橱</p><label><span>中文名</span><input name="name" lang="zh-CN" aria-label="中文名" required maxlength="100" value="${esc(names.name)}"></label><label><span>英文名</span><input name="nameEn" lang="en" aria-label="英文名" required maxlength="100" value="${esc(names.nameEn)}"></label><p class="tailor-name-error" role="alert"></p><div><button type="button" data-cancel>取消</button><button type="submit">保存为新衣服</button></div></form>`;dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.querySelector('form').oninput=()=>MobileTailor.rename(dialog.querySelector('[name=name]').value,dialog.querySelector('[name=nameEn]').value);dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const submit=dialog.querySelector('[type=submit]');submit.disabled=true;try{MobileTailor.rename(dialog.querySelector('[name=name]').value,dialog.querySelector('[name=nameEn]').value);await MobileTailor.save();dialog.close();}catch(error){dialog.querySelector('.tailor-name-error').textContent=error.message;submit.disabled=false;}};dialog.showModal();}
function handleTailor(b){if(MobileTailor.busy())return;const i=item(tailorItem);switch(b.dataset.tailorAction){case 'garment':openTailorGarment(i);break;case 'color':case 'print':tailorPanel=b.dataset.tailorAction;render();break;case 'retry':render();break;case 'reset':MobileTailor.resetDraft();render();break;case 'undo':MobileTailor.undo().then(()=>{render();}).catch(error=>toast(error.message));break;case 'draft':MobileEditUI.openDrafts('tailor');break;case 'save':openTailorNames();break;}}
function openTailorGarment(i){const dialog=$('#purchase-dialog');$('#purchase-content').innerHTML=`<h2 data-no-i18n>${esc(garmentLabel(i))}</h2><p>${itemPrice(i)} ${tailorText('积分','Points')}</p><button data-buy-tailor>${tailorText('解锁衣服','Unlock Item')}</button>`;$('#purchase-content').onclick=async e=>{const b=e.target.closest('[data-buy-tailor]');if(!b)return;b.disabled=true;try{const result=await PlayerEconomy.purchase(i.id,itemPrice(i));if(result.insufficient){toast(tailorText('积分不足','Not Enough Points'));b.disabled=false;return;}dialog.close();render();}catch(error){toast(error.message);b.disabled=false;}};dialog.showModal();}
I18n.register({'存草稿':'Save Draft','草稿已保存':'Draft Saved','给新衣服起名':'Name Your New Garment','保存后会作为独立衣服加入衣橱':'Saved as an independent item in your wardrobe','中文名':'Chinese Name','英文名':'English Name','衣服颜色':'Garment Color','搜索印花':'Search Prints','印花大小':'Print Size','水平位置':'Horizontal Position','垂直位置':'Vertical Position'});
window.addEventListener('language-changed',()=>{if(tab==='tailor')render();});

function normalizeHairLimit(){for(const [cat]of HAIR_CATEGORIES){const hair=HairStudio.consumer.get(),selected=selectedInCategory(hair,cat),limit=state.hairMode==='single'?1:2;if(selected.length>limit){for(const i of selected.slice(0,-limit))hair[i.side]=hair[i.side].filter(id=>id!==i.id);HairStudio.consumer.restore(hair);}}}
normalizeHairLimit();
I18n.register({'前':'Front','后':'Back','未选择单品':'No Piece Selected','未选择头发':'No Hair Selected','身体前':'In Front','身体后':'Behind','发梢前':'Tips in Front','发梢后':'Tips Behind','单选':'Single','多选 · 每类最多 2 款':'Multiple · Up to 2 per Category','全部取下':'Remove All','脸部':'Face','细节':'Detail','全身':'Full Body','保存':'Save','删除':'Delete','颜色名字':'Color Name','发色色号':'Hair Color Hex','发色名字':'Hair Color Name','改色':'Recolor','印花':'Print','恢复':'Reset','保存为新衣服':'Save as New Item','解锁改色 · 10 积分':'Unlock Recolor · 10 Points','每个分类最多选 2 款':'Up to 2 per Category','裁缝铺':'Tailor','还没有可改色或印花的衣服':'No Customizable Items Yet','已保存为新衣服':'Saved as a New Item'});
